INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(44711, 'Numbers 33:9', 'Numbers', 33, 9, 'بیا هغوی په ایلیم کې خېمې ودرولې چېرته چې د اوبو دولس چینې او اویا د خرما ونې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers33_verse_9.mp3', '', 1761754199, 1761754199),
(44712, 'Numbers 33:10', 'Numbers', 33, 10, 'هغوی د ایلیم څخه لاړل او د سرې بحیرې په غاړه یې خېمې ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers33_verse_10.mp3', '', 1761754199, 1761754199),
(44713, 'Numbers 33:11', 'Numbers', 33, 11, 'د سرې بحیرې څخه روان شول او د سین په دښته کې یې خېمې ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers33_verse_11.mp3', '', 1761754199, 1761754199),
(44714, 'Numbers 33:12', 'Numbers', 33, 12, 'بیا د سین د دښتې څخه لاړل او په دفقه کې یې خېمې ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers33_verse_12.mp3', '', 1761754199, 1761754199),
(44715, 'Numbers 33:13', 'Numbers', 33, 13, 'د دفقه څخه لاړل او په الوش کې یې خېمې ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers33_verse_13.mp3', '', 1761754199, 1761754199),
(44716, 'Numbers 33:14', 'Numbers', 33, 14, 'د الوش څخه لاړل او په رفیدیم کې یې خېمې ودرولې، چېرته چې د خلکو دپاره د څښلو اوبه نه وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers33_verse_14.mp3', '', 1761754199, 1761754199),
(44717, 'Numbers 33:15', 'Numbers', 33, 15, 'هغوی د رفیدیم څخه لاړل او په اخر کې د سینا دښتې ته ورسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers33_verse_15.mp3', '', 1761754199, 1761754199),
(44718, 'Numbers 33:37', 'Numbers', 33, 37, 'کله چې هغوی د قادش څخه لاړل، نو د هور د غره په څنګ کې یې د ادوم په سرحد کې خېمې ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers33_verse_37.mp3', '', 1761754199, 1761754199),
(44719, 'Numbers 33:38', 'Numbers', 33, 38, 'دا هغه ځای دی چې څښتن هارون کاهن ته امر وکړ چې د غره سرته وخېژي. هارون هلته د پنځمې میاشتې په لومړۍ ورځ څلوېښت کاله وروسته له دې چې اسراییلیان د مصر څخه تللي وو، مړ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers33_verse_38.mp3', '', 1761754199, 1761754199),
(44720, 'Numbers 33:39', 'Numbers', 33, 39, 'په هغه وخت کې هارون د یوسلو درویشتو کالو په عمر ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers33_verse_39.mp3', '', 1761754199, 1761754199),
(44721, 'Numbers 33:40', 'Numbers', 33, 40, 'د عراد کنعاني پاچا چې د کنعان په جنوب کې اوسېده، واورېدل چې اسراییلیان راروان دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers33_verse_40.mp3', '', 1761754199, 1761754199),
(44722, 'Numbers 33:48', 'Numbers', 33, 48, 'او په اخر کې د موآب په ډاګونو کې د اردن د سیند په بله غاړه اریحا ته مخامخ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers33_verse_48.mp3', '', 1761754199, 1761754199),
(44723, 'Numbers 33:49', 'Numbers', 33, 49, 'د هغوی کمپ د بیت یشیموت څخه تر آبل شطیم پورې غزېدلی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers33_verse_49.mp3', '', 1761754199, 1761754199),
(44724, 'Numbers 33:50', 'Numbers', 33, 50, 'کله چې د اسراییلو قوم د موآب په ډاګونو کې د اردن د سیند په غاړه اریحا ته مخامخ خېمې ودرولې وې، څښتن موسی ته وویل چې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers33_verse_50.mp3', '', 1761754199, 1761754199),
(44725, 'Numbers 33:51', 'Numbers', 33, 51, 'هغوی ته دا پیغام ورسوي: «کله چې تاسو د اردن د سیند څخه تېر شئ او کنعان ته ورننوځئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers33_verse_51.mp3', '', 1761754199, 1761754199),
(44726, 'Numbers 33:52', 'Numbers', 33, 52, 'باید د هغه ځای ټول اوسېدونکي وشړئ. د هغوی ټول د تیږو او فلزي بتان او ټول عبادتځایونه له منځه یوسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers33_verse_52.mp3', '', 1761754199, 1761754199),
(44727, 'Numbers 33:53', 'Numbers', 33, 53, 'هغه خاوره ونیسئ او په هغې کې واوسېږئ، ځکه چې هغه مې تاسو ته درکړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers33_verse_53.mp3', '', 1761754199, 1761754199),
(44728, 'Numbers 33:54', 'Numbers', 33, 54, 'هغه ځمکه د مختلفو قبیلو او طایفو ترمنځ د پچې له مخې ووېشئ، لویې طایفې ته زیاته ځمکه او کوچنۍ طایفې ته لږه ځمکه ورکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers33_verse_54.mp3', '', 1761754199, 1761754199),
(44729, 'Numbers 33:55', 'Numbers', 33, 55, 'که چېرې د هغه ځای ټول اوسېدونکي ونه شړئ، هغوی به ستاسو په سترګو کې د اغزیو او ستاسو په بدنونو کې به د کرکڼو په شان شي. هغوی به تل تاسو ته تکلیف درکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers33_verse_55.mp3', '', 1761754199, 1761754199),
(44730, 'Numbers 33:56', 'Numbers', 33, 56, 'که چېرې تاسو هغوی ونه شړئ، زه به تاسو تباه کړم لکه څنګه چې مې د هغوی د تباه کولو پلان جوړ کړی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers33_verse_56.mp3', '', 1761754199, 1761754199),
(44731, 'Joshua 19:1', 'Joshua', 19, 1, 'دوهمه پچه د شمعون د قبیلې د طایفو په نوم ووتله. د هغوی سیمه د یهودا په ځمکه کې پرته وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_1.mp3', '', 1761754199, 1761754199),
(44732, 'Joshua 19:2', 'Joshua', 19, 2, 'په هغې کې دا ځایونه شامل وو: بیرشبع (شبع)، مولاده،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_2.mp3', '', 1761754199, 1761754199),
(44733, 'Joshua 19:3', 'Joshua', 19, 3, 'حزر شوعال، بالح، عاصم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_3.mp3', '', 1761754199, 1761754199),
(44734, 'Joshua 19:4', 'Joshua', 19, 4, 'التولد، بتول، حرمه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_4.mp3', '', 1761754199, 1761754199),
(44735, 'Joshua 19:5', 'Joshua', 19, 5, 'صقلغ، بیت مرکبوت، حزر سوسه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_5.mp3', '', 1761754199, 1761754199),
(44736, 'Joshua 19:6', 'Joshua', 19, 6, 'بیت لباعوت او شاروحن - د شاوخوا کلیو سره دیارلس ښارګوټي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_6.mp3', '', 1761754199, 1761754199),
(44737, 'Joshua 19:7', 'Joshua', 19, 7, 'عین، رمون، عاتر او عاشان - د شاوخوا کلیو سره څلور ښارګوټي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_7.mp3', '', 1761754199, 1761754199),
(44738, 'Joshua 19:8', 'Joshua', 19, 8, 'په دې سیمه کې په جنوب کې تر بعلت بییر (جنوبي رامه) پورې ټول ښارګوټي او کلي شامل وو. دا هغه ځمکه وه چې د شمعون د قبیلې طایفو د خپل ملکیت په توګه تر لاسه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_8.mp3', '', 1761754199, 1761754199),
(44739, 'Joshua 19:9', 'Joshua', 19, 9, 'څرنګه چې د یهودا برخه د هغوی د اړتیا له اندازې څخه زیاته وه، نو د هغه د سیمې یوه برخه د شمعون قبیلې ته ورکړل شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_9.mp3', '', 1761754199, 1761754199),
(44740, 'Joshua 19:10', 'Joshua', 19, 10, 'درېمه پچه د زبولون د قبیلې د طایفو په نوم ووتله. هغه ځمکه چې هغوی تر لاسه کړه د سارید پورې رسېدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_10.mp3', '', 1761754199, 1761754199),
(44741, 'Joshua 19:11', 'Joshua', 19, 11, 'دا سرحد د هغه ځای څخه په لوېدیځه خوا کې مرعله ته تللی او د دباشه پورې رسېدلی او یقنعام ته نژدې ویالې ته تللی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_11.mp3', '', 1761754199, 1761754199),
(44742, 'Joshua 19:12', 'Joshua', 19, 12, 'دا سرحد د سارید ختیځې خواته د کسلوت تابور د سیمې پولې ته ګرځېدلی او دابره ته راوتلی او پورته تر یافیع پورې رسېدلی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_12.mp3', '', 1761754199, 1761754199),
(44743, 'Joshua 19:13', 'Joshua', 19, 13, 'بیا دا سرحد د ختیځ خواته د جت حافر او عت قاصین ته تللی، رمون ته راوتلی او د نیعه خواته ګرځېدلی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_13.mp3', '', 1761754199, 1761754199),
(44744, 'Joshua 19:14', 'Joshua', 19, 14, 'په شمال کې دا سرحد د حناتون خواته ګرځېدلی او د یفتح ییل په دره کې ختم شوی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_14.mp3', '', 1761754199, 1761754199),
(44745, 'Joshua 19:15', 'Joshua', 19, 15, 'زبولون د شاوخوا کلیو سره دولس ښارګوټي درلودل. د هغو څخه ځینې یې دا وو: قطه، نهلال، شمرون، یداله او بیت لحم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_15.mp3', '', 1761754199, 1761754199),
(44746, 'Joshua 19:16', 'Joshua', 19, 16, 'دا ښارګوټي او د هغو کلي په هغې ځمکه کې وو چې د زبولون د قبیلې طایفو د خپل ملکیت په توګه تر لاسه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_16.mp3', '', 1761754199, 1761754199),
(44747, 'Joshua 19:17', 'Joshua', 19, 17, 'څلورمه پچه د یساکار د قبیلې د طایفو په نوم ووتله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_17.mp3', '', 1761754199, 1761754199),
(44748, 'Joshua 19:18', 'Joshua', 19, 18, 'د هغوی په سیمه کې دا ځایونه شامل وو: یزرعیل، کسلوت، شونم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_18.mp3', '', 1761754199, 1761754199),
(44749, 'Joshua 19:19', 'Joshua', 19, 19, 'حفارایم، شییون، اناحره،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_19.mp3', '', 1761754199, 1761754199),
(44750, 'Joshua 19:20', 'Joshua', 19, 20, 'ربیت، قشیون، آبص،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_20.mp3', '', 1761754199, 1761754199),
(44751, 'Joshua 19:21', 'Joshua', 19, 21, 'رمه، عین جنیم، عین حده او بیت فسیس.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_21.mp3', '', 1761754199, 1761754199),
(44752, 'Joshua 19:22', 'Joshua', 19, 22, 'او دا سرحد د تابور غره، شحصیمه او بیت شمس ته رسېدلی او د اردن د سیند سره ختم شوی دی. په هغه کې شپاړس ښارګوټي د هغو د شاوخوا کلیو سره شامل وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_22.mp3', '', 1761754199, 1761754199),
(44753, 'Joshua 19:23', 'Joshua', 19, 23, 'دا ښارګوټي او د هغو کلي په هغې ځمکه کې وو چې د یساکار د قبیلې طایفو د خپل ملکیت په توګه تر لاسه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_23.mp3', '', 1761754199, 1761754199),
(44754, 'Joshua 19:24', 'Joshua', 19, 24, 'پنځمه پچه د اشیر د قبیلې د طایفو په نوم ووتله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_24.mp3', '', 1761754199, 1761754199),
(44755, 'Joshua 19:25', 'Joshua', 19, 25, 'د هغوی په سیمه کې دا ځایونه شامل وو: حلقات، حلي، باطن، اکشاف،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_25.mp3', '', 1761754199, 1761754199),
(44756, 'Joshua 19:26', 'Joshua', 19, 26, 'الملک، عمعاد او مشال. په لوېدیځ کې دا سرحد کرمل او شیحور لبنه ته رسېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_26.mp3', '', 1761754199, 1761754199),
(44757, 'Joshua 19:27', 'Joshua', 19, 27, 'بیا د هغه ځای څخه ختیځې خواته بیت داجون ته ګرځېدلی، د زبولون او د یفتح ییل تر درې پورې رسېدلی دی او په شمال کې بیت عامق او نعي ییل ته راوتلی دی. دا سرحد د شمال خواته د کابول،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_27.mp3', '', 1761754199, 1761754199),
(44758, 'Joshua 19:28', 'Joshua', 19, 28, 'عبرون، رحوب، حمون، قانه او تر لوی صیدون پورې غزېدلی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_28.mp3', '', 1761754199, 1761754199),
(44759, 'Joshua 19:29', 'Joshua', 19, 29, 'دا سرحد بیا رامه ته ګرځېدلی او د صور قوي دېوال لرونکي ښار ته رسېده. بیا هغه حوسه ته ګرځېدلی او د مدیترانې په بحیره کې ختم شوی دی. په دې سیمه کې محالاب، اکزیب،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_29.mp3', '', 1761754199, 1761754199),
(44760, 'Joshua 19:30', 'Joshua', 19, 30, 'عمه، عفیق او رحوب شامل وو. د شاوخوا کلیو سره دوه ویشت ښارګوټي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_30.mp3', '', 1761754199, 1761754199),
(44761, 'Joshua 19:31', 'Joshua', 19, 31, 'دا ښارګوټي او د هغو کلي په هغې ځمکه کې وو چې د اشیر د قبیلې طایفو د خپل ملکیت په توګه تر لاسه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_31.mp3', '', 1761754199, 1761754199),
(44762, 'Joshua 19:32', 'Joshua', 19, 32, 'شپږمه پچه د نفتالي د قبیلې د طایفو په نوم ووتله:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_32.mp3', '', 1761754199, 1761754199),
(44763, 'Joshua 19:33', 'Joshua', 19, 33, 'د هغوی سرحد د حالف او په صعنیم کې د څېړۍ د ونې څخه تېر شوی او د ادامي ناقب او یبنییل څخه تر لقوم پورې رسېده او د اردن د سیند سره ختم شوی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_33.mp3', '', 1761754199, 1761754199),
(44764, 'Joshua 19:34', 'Joshua', 19, 34, 'په هغه ځای کې دا سرحد لوېدیځې خواته د ازنوت تابور په لور ګرځېدلی او په حقوق کې راوتلی دی. هغه په جنوب کې د زبولون سیمې ته، په لوېدیځ کې د اشیر سیمې ته او په ختیځ کې د اردن سیند ته رسېدلی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_34.mp3', '', 1761754199, 1761754199),
(44765, 'Joshua 19:35', 'Joshua', 19, 35, 'هغه قوي دېوال لرونکي ښارګوټي دا وو: صدیم، صیر، حمت، رقت، کنارت،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_35.mp3', '', 1761754199, 1761754199),
(44766, 'Joshua 19:36', 'Joshua', 19, 36, 'ادامه، رامه، حاصور،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_36.mp3', '', 1761754199, 1761754199),
(44767, 'Joshua 19:37', 'Joshua', 19, 37, 'قادش، ادرعي، عین حاصور،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_37.mp3', '', 1761754199, 1761754199),
(44768, 'Joshua 19:38', 'Joshua', 19, 38, 'یرون، مجدل ییل، حوریم، بیت عناه او بیت شمس. د شاوخوا کلیو سره نولس ښارګوټي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_38.mp3', '', 1761754199, 1761754199),
(44769, 'Joshua 19:39', 'Joshua', 19, 39, 'دا ښارګوټي او د هغو کلي په هغې ځمکه کې وو چې د نفتالي د قبیلې طایفو د خپل ملکیت په توګه تر لاسه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_39.mp3', '', 1761754199, 1761754199),
(44770, 'Joshua 19:40', 'Joshua', 19, 40, 'اوومه پچه د دان د قبیلې د طایفو په نوم ووتله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_40.mp3', '', 1761754199, 1761754199),
(44771, 'Joshua 19:41', 'Joshua', 19, 41, 'د هغوی په سیمه کې دا ځایونه شامل وو: زرعه، اشتاول، عیر شمس،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_41.mp3', '', 1761754199, 1761754199),
(44772, 'Joshua 19:42', 'Joshua', 19, 42, 'شعلبین، ایالون، یتله،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_42.mp3', '', 1761754199, 1761754199),
(44773, 'Joshua 19:43', 'Joshua', 19, 43, 'ایلون، تمنه، عقرون،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_43.mp3', '', 1761754199, 1761754199),
(44774, 'Joshua 19:44', 'Joshua', 19, 44, 'التقي، جبتون، بعله،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_44.mp3', '', 1761754199, 1761754199),
(44775, 'Joshua 19:45', 'Joshua', 19, 45, 'یهود، بني برق، جت رمون،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_45.mp3', '', 1761754199, 1761754199),
(44776, 'Joshua 19:46', 'Joshua', 19, 46, 'میاه یرقون او رقون د هغې سیمې سره چې یافا ته مخامخ وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_46.mp3', '', 1761754199, 1761754199),
(44777, 'Joshua 19:49', 'Joshua', 19, 49, 'کله چې د اسراییلو قوم د ځمکې د وېشلو څخه وزګار شو، هغوی د نون زوی یوشع ته د ځمکې یوه برخه ورکړه چې د هغه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_49.mp3', '', 1761754199, 1761754199),
(44778, 'Joshua 19:50', 'Joshua', 19, 50, 'څنګه چې څښتن حکم کړی ؤ، هغوی یوشع ته هغه ښارګوټی ورکړ چې هغه غوښتی ؤ، یعنې تمنه سارح چې د افرایم په غرنۍ سیمه کې ؤ. هغه دا ښارګوټی بیا ودان کړ او هلته ځای په ځای شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_50.mp3', '', 1761754199, 1761754199),
(44779, 'Joshua 19:51', 'Joshua', 19, 51, 'دا هغه سیمې وې چې العازار کاهن، یوشع او د اسراییلو د قبیلو د طایفو مشرانو په شیلوه کې د پچې له مخې ووېشلې. هغوی دا کار د څښتن په حضور کې د سپېڅلې خېمې په دروازه کې وکړ. په دې ډول هغوی د ځمکې وېش سرته ورساوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua19_verse_51.mp3', '', 1761754199, 1761754199),
(44780, 'Obadiah 1:1', 'Obadiah', 1, 1, 'دا د عبدياه رويا ده. دا هغه څۀ دى چې مالِک خُدائ يې د ادوم د قوم په حقله فرمائى، مونږ د مالِک خُدائ نه يو پېغام واورېدو، هغۀ يو پېغمبر قومونو ته ولېږلو چې ورته وفرمائى، ”پاڅئ، او راځئ چې په ادوم حمله وکړُو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/obadiah1_verse_1.mp3', '', 1761754199, 1761754199),
(44781, 'Obadiah 1:2', 'Obadiah', 1, 2, 'اے ادومه ګوره، زۀ به تا په قومونو کښې وړوکے کړم، تۀ به ډېر سپک شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/obadiah1_verse_2.mp3', '', 1761754199, 1761754199),
(44782, 'Obadiah 1:3', 'Obadiah', 1, 3, 'تۀ خپل غرور دوکه کړے يې، تۀ چې د غرونو په غارونو کښې اوسېږې، او په اوچتو ځايونو کښې خپل کور جوړوې، تۀ چې د خپل ځان سره وائې چې، ”څوک ما لاندې زمکې ته راوستلے شى؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/obadiah1_verse_3.mp3', '', 1761754199, 1761754199),
(44783, 'Obadiah 1:4', 'Obadiah', 1, 4, 'خو تر دې کۀ تاسو د باز په شان اوچت هم والوځئ، او خپله جاله د ستورو سره جوړه کړئ، نو زۀ به هلته نه هم تاسو لاندې راولم، مالِک خُدائ فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/obadiah1_verse_4.mp3', '', 1761754199, 1761754199),
(44784, 'Obadiah 1:5', 'Obadiah', 1, 5, 'کۀ غلۀ د شپې راشى او تا لوټ کړى، نو هغوئ به تا نه دومره څۀ پټ کړى څومره چې غواړى. کله چې خلق انګور راټولوى نو څۀ نه څۀ ترې نه پاتې شى. خو ستاسو دشمن به تاسو مکمل جارُو کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/obadiah1_verse_5.mp3', '', 1761754199, 1761754199),
(44785, 'Obadiah 1:6', 'Obadiah', 1, 6, 'د ادوم خلق، د عِيسو اولاد به په پوره توګه لوټ کړے شى، او د هغوئ پټې خزانې به يوړے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/obadiah1_verse_6.mp3', '', 1761754199, 1761754199),
(44786, 'Obadiah 1:7', 'Obadiah', 1, 7, 'تر دې چې ستا ټول اِتحاديان به هم تا ستا د خپل مُلک نه وزغلوى، ستا خپل ملګرى به تا دوکه کړى او په تا به زورَور شى. ستا اعتبارى دوستان به تا ته دام خور کړى، خو تا ته به دا معلوم نۀ وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/obadiah1_verse_7.mp3', '', 1761754199, 1761754199),
(44787, 'Obadiah 1:8', 'Obadiah', 1, 8, 'مالِک خُدائ فرمائى، په هغه ورځ به د ادوم په ټوله علاقه کښې يو هوښيار کس هم باقى پاتې نۀ شى، ځکه چې د ادوم په غرونو به زۀ هغه هر يو کس تباه کړم څوک چې عقل لرى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/obadiah1_verse_8.mp3', '', 1761754199, 1761754199),
(44788, 'Obadiah 1:9', 'Obadiah', 1, 9, 'اے تيمانه، ستا جنګيالى به ويريږى، او د ادوم په غرونو کښې هر يو کس به حلال کړے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/obadiah1_verse_9.mp3', '', 1761754199, 1761754199),
(44789, 'Obadiah 1:10', 'Obadiah', 1, 10, 'تا خپل ورور يعقوب سره ظلم کړے دے نو په دې وجه به تۀ په شرمونو وشرمېږې او د همېشه دپاره به تباه او برباد شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/obadiah1_verse_10.mp3', '', 1761754199, 1761754199),
(44790, 'Obadiah 1:11', 'Obadiah', 1, 11, 'په هغه ورځ تۀ لرې ولاړ وې کله چې غېر مُلکيان د هغۀ دروازو ته ورننوتل او د هغۀ نه يې مال دولت يوړلو، او د يروشلم د تقسيمولو دپاره يې پچه واچوله. نو تا په هيڅ نۀ کولو داسې رويه خپله کړې وه لکه چې تۀ هم د بنى اِسرائيلو دشمن يې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/obadiah1_verse_11.mp3', '', 1761754199, 1761754199),
(44791, 'Obadiah 1:12', 'Obadiah', 1, 12, 'تا له د خپل ورور د بد قسمتۍ په ورځ خوشحالېدل نۀ دى پکار، او نۀ درله د يهوداه د خلقو د تباهۍ په ورځ خوشحالېدل پکار دى، او نۀ درله د هغوئ د تکليف په ورځ لافې کول په کار دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/obadiah1_verse_12.mp3', '', 1761754199, 1761754199),
(44792, 'Obadiah 1:13', 'Obadiah', 1, 13, 'تا له نۀ وو په کار چې زما د خلقو دروازو ته ننوتلے وې د هغوئ د تباهۍ په ورځ، او نۀ درله په کار وو چې تۀ د هغوئ د تباهۍ په ورځ د هغوئ په مصيبت باندې خوشحاله شوے وې، او نۀ د هغوئ د تباهۍ په ورځ هغوئ لوټ کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/obadiah1_verse_13.mp3', '', 1761754199, 1761754199),
(44793, 'Obadiah 1:14', 'Obadiah', 1, 14, 'تا له نۀ وو په کار چې په چوکونو کښې ولاړ وې او هغوئ دې وژل څوک چې تښتېدل. تا له نۀ وو پکار چې هغه بچ شوى خلق دې نيول او دشمن ته دې حواله کول، په کومه ورځ چې هغوئ په مصيبت کښې وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/obadiah1_verse_14.mp3', '', 1761754199, 1761754199),
(44794, 'Obadiah 1:15', 'Obadiah', 1, 15, 'د مالِک خُدائ د قيامت ورځ رانزدې ده، د ټولو قومونو دپاره. څنګه چې تاسو کړى دى، نو هم داسې به تاسو سره هم وشى. ستاسو عملونه به واپس ستاسو په خپل سر راشى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/obadiah1_verse_15.mp3', '', 1761754199, 1761754199),
(44795, 'Obadiah 1:16', 'Obadiah', 1, 16, 'اول تاسو زما په مقدس غرۀ زما د غضب جام وڅښلو، خو اوس به يې نور ټول قومونه څښى. بلکې هغوئ به دا په څښلو څښلو خالى کړى، او هغوئ به دې آخرى قطرې هم څټى. بيا به د هغوئ نام و نشان باقى پاتې نۀ شى، داسې به ښکارى لکه هغوئ چې بلکل وُو نه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/obadiah1_verse_16.mp3', '', 1761754199, 1761754199),
(44796, 'Obadiah 1:17', 'Obadiah', 1, 17, 'خو د صيون غر به د هغوئ دپاره د پناه ځائ شى څوک چې تښتى، دا به مقدس وى. او د يعقوب اولاد به دا ځائ د خپل ميراث په توګه قبضه کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/obadiah1_verse_17.mp3', '', 1761754199, 1761754199),
(44797, 'Obadiah 1:18', 'Obadiah', 1, 18, 'د يعقوب اولاد به لکه د اور په شان وى او د يوسف اولاد به لکه لمبه وى، او ادوم به لکه د بوسو په پوره توګه وسوزوى. د ادوم په اولاد کښې به څوک هم ژوندى پاتې نۀ شى. مالِک خُدائ دا فرمائيلى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/obadiah1_verse_18.mp3', '', 1761754199, 1761754199),
(44798, 'Obadiah 1:19', 'Obadiah', 1, 19, 'د نجب خلق به د ادوم غرونه قبضه کړى، او د ښکته علاقو خلق به د فلستيه مُلک قبضه کړى، هغوئ به د اِفرائيم او سامريه علاقې قبضه کړى، او د بنيامين خلق به جِلعاد قبضه کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/obadiah1_verse_19.mp3', '', 1761754199, 1761754199),
(44799, 'Obadiah 1:20', 'Obadiah', 1, 20, 'د بنى اِسرائيلو جلاوطن کړے شوى خلق چې په کنعان کښې دى به د صارفت پورې مُلک قبضه کړى، د يروشلم جلاوطن کړے شوى څوک چې په سفاراد کښې دى هغوئ به د نجب په ښارونو قبضه وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/obadiah1_verse_20.mp3', '', 1761754199, 1761754199),
(44800, 'Obadiah 1:21', 'Obadiah', 1, 21, 'خلاصون ورکونکى به د صيون غرۀ ته بره وخېژى چې د ادوم په غرونو باندې حکومت وکړى. او مالِک خُدائ به پخپله بادشاه وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/obadiah1_verse_21.mp3', '', 1761754199, 1761754199),
(44801, 'Psalms 132:1', 'Psalms', 132, 1, 'ای څښتنه، در په یاد کړه داود ټولې سختۍ یې چې زغملې در په یاد کړه هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms132_verse_1.mp3', '', 1761754199, 1761754199),
(44802, 'Psalms 132:2', 'Psalms', 132, 2, 'ای څښتنه، در په یاد هغه قسم کړه چې هغه کړی ؤ او نذر یې ورکړ ستا په نوم: «ای د یعقوب قادره خدایه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms132_verse_2.mp3', '', 1761754199, 1761754199),
(44803, 'Psalms 132:3', 'Psalms', 132, 3, 'نه به زه لاړ شمه خپل کور ته او نه به وکړمه ارام خپل کټ کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms132_verse_3.mp3', '', 1761754199, 1761754199),
(44804, 'Psalms 132:4', 'Psalms', 132, 4, 'زه به نه شم ویده او یوه شېبه به هم ارام ونه کړم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms132_verse_4.mp3', '', 1761754199, 1761754199),
(44805, 'Psalms 132:5', 'Psalms', 132, 5, 'ترڅو تیار نه کړمه ځای زه د څښتن دپاره او د اوسېدو ځای د یعقوب د قادر خدای دپاره»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms132_verse_5.mp3', '', 1761754199, 1761754199),
(44806, 'Psalms 132:6', 'Psalms', 132, 6, 'د لوظ صندوق نه شو خبر په افراته کې او هغه مو وموند د یعاریم سیمه کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms132_verse_6.mp3', '', 1761754199, 1761754199),
(44807, 'Psalms 132:7', 'Psalms', 132, 7, 'مونږ داسې وویل: «راځئ چې لاړ شو د څښتن د اوسېدو ځای ته راځئ چې وکړو عبادت د هغه د تخت مخې ته»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms132_verse_7.mp3', '', 1761754199, 1761754199),
(44808, 'Psalms 132:8', 'Psalms', 132, 8, 'راشه خپل کور ته ای څښتنه، د لوظ د صندوق سره چې ده نښه د قدرت ستا او هلته اوسه ته د تل دپاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms132_verse_8.mp3', '', 1761754199, 1761754199),
(44809, 'Psalms 132:9', 'Psalms', 132, 9, 'ستا کاهنان دې ځان سمبال کړي د صداقت په لباس ستا وفادار خلک دې وهي د خوشحالۍ چیغې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms132_verse_9.mp3', '', 1761754199, 1761754199),
(44810, 'Psalms 132:10', 'Psalms', 132, 10, 'خپل خدمتګار داود په خاطر مخ مه اړوه د خپل غوره شوي پاچا څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms132_verse_10.mp3', '', 1761754199, 1761754199);